// Generates lib/db/migrations-manifest.ts from supabase/migrations/*.sql.
// Run automatically before `dev` and `build` (see package.json scripts) so the
// embedded SQL is always in sync with the migration files. The generated file
// is committed, so a plain `next build` also works.
//
// Why a generated manifest instead of reading the folder at runtime: Next.js
// output file tracing only bundles IMPORTED modules — supabase/migrations/*.sql
// would be missing from the serverless bundle on Vercel. Embedding the SQL as
// a TypeScript module guarantees the auto-setup has its migration set everywhere.
import { readdirSync, readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";

const MIGRATIONS_DIR = join(process.cwd(), "supabase", "migrations");
const OUT_FILE = join(process.cwd(), "lib", "db", "migrations-manifest.ts");

const files = readdirSync(MIGRATIONS_DIR)
  .filter((f) => f.endsWith(".sql"))
  .sort(); // timestamp-prefixed filenames => chronological apply order

if (files.length === 0) {
  console.error("[migrations-manifest] no .sql files found in supabase/migrations — aborting");
  process.exit(1);
}

const seen = new Set();
const entries = files.map((filename) => {
  const version = filename.split("_")[0];
  if (!/^\d{14}$/.test(version)) {
    console.error(`[migrations-manifest] ${filename}: expected a 14-digit timestamp prefix (YYYYMMDDHHMMSS_name.sql)`);
    process.exit(1);
  }
  if (seen.has(version)) {
    console.error(`[migrations-manifest] duplicate migration version ${version} (${filename})`);
    process.exit(1);
  }
  seen.add(version);
  const name = filename.slice(version.length + 1).replace(/\.sql$/, "");
  const sql = readFileSync(join(MIGRATIONS_DIR, filename), "utf8");
  return { version, name, filename, sql };
});

const body = `// AUTO-GENERATED by scripts/generate-migrations-manifest.mjs — DO NOT EDIT.
// Source of truth: supabase/migrations/*.sql (regenerate with: node scripts/generate-migrations-manifest.mjs)
// Embedded so the WordPress-style auto DB setup works inside bundled deploys
// (Vercel) where the migrations folder is not part of the server output.
export interface MigrationFile {
  /** 14-digit timestamp prefix, e.g. 20261110130000 */
  version: string;
  /** Human-readable migration name from the filename */
  name: string;
  /** Original filename in supabase/migrations/ */
  filename: string;
  /** Full SQL text, applied as one simple-query transaction */
  sql: string;
}

export const MIGRATIONS: MigrationFile[] = [
${entries
  .map(
    (e) => `  {
    version: ${JSON.stringify(e.version)},
    name: ${JSON.stringify(e.name)},
    filename: ${JSON.stringify(e.filename)},
    sql: ${JSON.stringify(e.sql)},
  },`
  )
  .join("\n")}
];

export const LATEST_MIGRATION_VERSION = MIGRATIONS[MIGRATIONS.length - 1]?.version ?? null;
`;

mkdirSync(join(process.cwd(), "lib", "db"), { recursive: true });
writeFileSync(OUT_FILE, body, "utf8");
console.log(`[migrations-manifest] embedded ${entries.length} migration(s) -> ${OUT_FILE.replace(process.cwd() + "/", "")}`);
entries.forEach((e) => console.log(`  ${e.version}  ${e.name} (${(e.sql.length / 1024).toFixed(1)} kB)`));
